import{at as e,it as t,n,vt as r}from"./chunks/framework.fhiXEbOi.js";var i=JSON.parse(`{"title":"Try Pay-to-Play with a local wallet","description":"Create a local test channel, deposit 100 wei and remove the disposable fixture.","frontmatter":{"title":"Try Pay-to-Play with a local wallet","description":"Create a local test channel, deposit 100 wei and remove the disposable fixture.","outline":false},"headers":[],"relativePath":"start/local-wallet.md","filePath":"start/local-wallet.md"}`),a={name:`start/local-wallet.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="try-pay-to-play-with-a-local-wallet" tabindex="-1">Try Pay-to-Play with a local wallet <a class="header-anchor" href="#try-pay-to-play-with-a-local-wallet" aria-label="Permalink to “Try Pay-to-Play with a local wallet”">​</a></h1><div class="ported-guide"><p>Create a test channel and deposit 100 wei. You will use public fixture accounts on a disposable local blockchain, not your real wallet.</p><dl><dt>Run on</dt><dd>Your workstation, from the source checkout.</dd><dt>Requires</dt><dd><a href="../build/setup.html">Development prerequisites</a>, a local Docker context and Chrome or Chromium.</dd><dt>Changes</dt><dd>Local containers, temporary chain state and a dedicated browser profile. No public-chain transaction.</dd><dt>Success</dt><dd>A successful deposit receipt and a 100-wei balance in the selected test position.</dd></dl><h2 id="launch">1. Start the app — terminal A</h2><p>Run from the source checkout. Replace <code>your-local-context</code> here and in the later commands with the same local engine:</p><pre><code>make dapps/deps/install DOCKER_CONTEXT=your-local-context &amp;&amp;
make js/deps/install DOCKER_CONTEXT=your-local-context &amp;&amp;
make pay-to-play/local/demo/gui/up \\
  DOCKER_CONTEXT=your-local-context COMPOSE_PROJECT_NAME=cam-demo</code></pre><p>Leave the foreground command running. It deploys a fresh app on Anvil chain 31337 and prints a complete viewer URL, normally at <code>http://127.0.0.1:5175</code>. A fresh chain has only reserve channel 0; do not reuse an assumed service-channel ID from an earlier run.</p><h2 id="wallet">2. Open the test browser and attach — terminals B and C</h2><p>Follow <a href="./fixture-wallet.html#browser">the shared isolated-browser step</a> in terminal B. Open terminal A&#39;s <strong>entire printed URL</strong> in that browser, including its query parameters. Do not use a profile containing a real wallet.</p><p>In terminal C, from the same checkout:</p><pre><code>make viewer/local/fixture-wallet/attach \\
  DOCKER_CONTEXT=your-local-context COMPOSE_PROJECT_NAME=cam-demo \\
  FIXTURE_WALLET_APP=pay-to-play \\
  CDP_ORIGIN=http://127.0.0.1:9222</code></pre><p>Select the matching tab if prompted, then connect the fixture wallet in the app. Keep both A and C running. The role selector starts on <strong>customer</strong>. The shared guide explains <a href="./fixture-wallet.html#send">browser confirmation</a>, <a href="./fixture-wallet.html#refresh">reloads</a> and <a href="./fixture-wallet.html#stop">detachment</a>.</p><h2 id="channel">3. Create a channel as admin</h2><p>Select <strong>admin</strong> in the fixture wallet and wait for the app to update. Open channel creation. For this local experiment, use the admin&#39;s displayed address as both payee and collector and choose a 60-second claim period.</p><p>Review the call, choose <strong>Send with wallet</strong> and confirm in the <strong>browser dialog</strong>. Read the channel ID from the successful receipt&#39;s <code>ChannelCreated</code> event, not from an observed channel count.</p><h2 id="deposit">4. Deposit as customer</h2><p>Select <strong>customer</strong> and wait for the refreshed view. Open a balance using that customer&#39;s displayed address and the channel ID from the receipt. Choose <strong>Deposit</strong> and enter <strong>100 in the wei/base-unit input</strong>, not 100 whole coins.</p><p>Review, send and confirm in the browser. Check the successful receipt and the resulting 100-wei balance. The six task destinations remain visible; <strong>Balance</strong> is the overview. Funding does not authorize a voucher payment: <a href="../use/pay-to-play/#keys">registering a key and signing a voucher</a> are separate tasks.</p><h2 id="stop">5. Stop what you started</h2><p>Stop terminal C first to remove the injected wallet without closing the tab. Stop terminal A and let cleanup finish. To explicitly remove this demo:</p><pre><code>make pay-to-play/local/demo/gui/down \\
  DOCKER_CONTEXT=your-local-context COMPOSE_PROJECT_NAME=cam-demo</code></pre><p>Close the dedicated browser. Its profile remains on disk; the fixture&#39;s chain state is disposable. Closing a tab alone does not stop the app. For wallet/role mismatches, use the <a href="./fixture-wallet.html">shared attachment guide</a>; for a persistent website, use <a href="../deploy/viewer.html">Deploy the viewer</a>.</p><p>Source: <a href="https://github.com/numpde/dapp32/blob/04a18763700bbaa25cad73b9806d236ab4d5e139/dapps/pay-to-play/README.md#run-the-disposable-local-demo">demo startup</a> and <a href="https://github.com/numpde/dapp32/blob/04a18763700bbaa25cad73b9806d236ab4d5e139/js/tools/browser-fixture-wallet.mjs#L243-L254">fixture send confirmation</a>.</p></div>`,2)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};